CREATE OR REPLACE FUNCTION public.core_swap_integrity_update_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND OLD.reason IN ('CORE_SWAP','CORE_SWAP_V2') AND OLD.points>0 THEN IF (NEW.points,NEW.user_id,NEW.wallet_address,NEW.chain_id,NEW.tx_hash,NEW.source_log_index,NEW.verified_activity_id,NEW.verified_usd,NEW.policy_version,NEW.reason) IS DISTINCT FROM (OLD.points,OLD.user_id,OLD.wallet_address,OLD.chain_id,OLD.tx_hash,OLD.source_log_index,OLD.verified_activity_id,OLD.verified_usd,OLD.policy_version,OLD.reason) THEN RAISE EXCEPTION 'Historical reward economics and identity are immutable'; END IF; IF NEW.provenance_state IS DISTINCT FROM OLD.provenance_state THEN RAISE EXCEPTION 'Independent historical provenance approval workflow required'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER core_swap_integrity_update_guard BEFORE UPDATE ON public.flow_points_ledger FOR EACH ROW EXECUTE FUNCTION public.core_swap_integrity_update_guard();
CREATE OR REPLACE FUNCTION public.reward_funding_hash(p_ids uuid[]) RETURNS text LANGUAGE sql STABLE SET search_path=public AS $$ SELECT encode(sha256(convert_to(coalesce(string_agg(jsonb_build_array(l.id,l.user_id,l.points,l.base_points,l.reason,l.policy_version,l.chain_id,l.tx_hash,l.source_log_index,l.verified_activity_id,l.verified_usd,l.wallet_address,l.day_key,l.program_id,l.funding_state,l.reservation_id,l.provenance_state,p.wallet_address)::text,',' ORDER BY l.id),''),'UTF8')),'hex') FROM public.flow_points_ledger l LEFT JOIN public.profiles p ON p.id=l.user_id WHERE l.id=ANY(p_ids) $$;
CREATE OR REPLACE FUNCTION public.assert_publication_provenance() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE b public.reward_settlement_batches; leaf jsonb; eligible numeric; BEGIN IF TG_OP='INSERT' THEN SELECT * INTO b FROM public.reward_settlement_batches WHERE id=NEW.batch_id FOR UPDATE; IF b.publication_verified_at IS NULL THEN FOR leaf IN SELECT * FROM jsonb_array_elements(b.leaves) LOOP SELECT coalesce(sum(l.points),0) INTO eligible FROM public.flow_points_ledger l JOIN public.reward_reservations r ON r.ledger_id=l.id AND r.reservation_id=l.reservation_id AND r.points=l.points AND r.user_id=l.user_id AND lower(r.wallet_address)=lower(l.wallet_address) AND r.program_id=l.program_id JOIN public.profiles p ON p.id=l.user_id AND lower(p.wallet_address)=lower(l.wallet_address) WHERE lower(l.wallet_address)=lower(leaf->>'account') AND l.funding_state='FUNDED' AND (l.reason IN ('SIGNUP_BONUS_REFEREE','REFERRAL_SIGNUP_BONUS') OR (l.reason IN ('CORE_SWAP','CORE_SWAP_V2') AND l.chain_id=677 AND l.provenance_state='VERIFIED')); IF eligible*1e18 < (leaf->>'amount')::numeric THEN RAISE EXCEPTION 'Independent reward provenance unresolved; publication blocked'; END IF; END LOOP; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER assert_publication_provenance BEFORE INSERT ON public.reward_publish_attempts FOR EACH ROW EXECUTE FUNCTION public.assert_publication_provenance();